  {
    /* Transfer complete Callback for memory1 */
    hdma->XferM1CpltCallback(hdma);
    // Let's see what we did:
    // So, if CT = 1, we call "DMA transfer complete Memory1" callback
    // Let's think, what would the user do in the handler of such callback?
    // I'd argue, that when Memory 1 completed, DMA switched activity to Memory 0,
    // And it is time to update Memory 1, right?
    // For this, in the callback handler we write to DMA_SxM1AR address register ...
    // ...
    // But the CT is 1!!! According to RM 16.5.9 , we are not allowed to write to DMA_SxM1AR when CT is 1!!!
    // If we try, we fall into DMA Transfer Error
  }
}
/* Current memory buffer used is Memory 0 */
else // CT=0
{
  if(hdma->XferCpltCallback != NULL)
  {
    /* Transfer complete Callback for memory0 */
    hdma->XferCpltCallback(hdma);
    // Here the same problem for the other buffer
  }
}

